{"file_path":"./src/diff.js","content":"/**
 * Longest common subsequence of two documents (arrays of lines), matched
 * whole-line, with the earliest-match tie-break: when several longest
 * subsequences exist, prefer the one whose matches occur as early as
 * possible, advancing the base side on ties.
 */

/** Build the standard LCS length table: dp[i][j] = LCS length of base[i:] and side[j:]. */
function buildTable(base, side) {
  const n = base.length
  const m = side.length
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = dp[i]
    const nextRow = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) row[j] = nextRow[j + 1] + 1
      else row[j] = Math.max(nextRow[j], row[j + 1])
    }
  }
  return dp
}

/** Walk the table from the start, producing the chosen matched pairs [baseIndex, sideIndex]. */
function backtrack(base, side, dp) {
  const n = base.length
  const m = side.length
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Turn the chosen matches into a list of changes: maximal stretches where
 * the alignment does not match, each a run of base lines replaced by a run
 * of side lines (either run may be empty).
 */
function changesFromMatches(base, side, matches) {
  const changes = []
  let prevI = -1
  let prevJ = -1
  const points = matches.concat([[base.length, side.length]])
  for (const [i, j] of points) {
    if (i - prevI - 1 > 0 || j - prevJ - 1 > 0) {
      changes.push({ baseStart: prevI + 1, baseEnd: i, sideStart: prevJ + 1, sideEnd: j })
    }
    prevI = i
    prevJ = j
  }
  return changes
}

/** Compute the ordered list of changes turning `base` into `side`. */
export function computeChanges(base, side) {
  const dp = buildTable(base, side)
  const matches = backtrack(base, side, dp)
  return changesFromMatches(base, side, matches)
}
